// document (e.g. a linked skill was renamed).
func (q *Queries) TouchEvidence(ctx context.Context, arg TouchEvidenceParams) (int32, error) {
	row := q.db.QueryRow(ctx, touchEvidence, arg.UserID, arg.ID)
	var version int32
	err := row.Scan(&version)
	return version, err
}

const updateEvidence = `-- name: UpdateEvidence :one
UPDATE evidence SET
    organization_id = $4, category = $5, form = $6, kind = $7, title = $8, summary = $9,
    location = $10, url = $11, start_date = $12, start_precision = $13, end_date = $14,
    end_precision = $15, is_current = $16, details = $17, auto_include = $18, content_hash = $19,
    position = $20, version = version + 1, updated_at = now()
WHERE user_id = $1 AND id = $2 AND version = $3
RETURNING version
`

type UpdateEvidenceParams struct {
	UserID         uuid.UUID
	ID             uuid.UUID
	Version        int32
	OrganizationID *uuid.UUID
	Category       EvidenceCategory
	Form           EvidenceForm
	Kind           string
	Title          string
	Summary        string
	Location       string
	Url            string
	StartDate      *time.Time
	StartPrecision *DatePrecision
	EndDate        *time.Time
	EndPrecision   *DatePrecision
	IsCurrent      bool
	Details        json.RawMessage
	AutoInclude    bool
	ContentHash    []byte
	Position       string
}

func (q *Queries) UpdateEvidence(ctx context.Context, arg UpdateEvidenceParams) (int32, error) {
	row := q.db.QueryRow(ctx, updateEvidence,
		arg.UserID,
		arg.ID,
		arg.Version,
		arg.OrganizationID,
		arg.Category,
		arg.Form,
		arg.Kind,
		arg.Title,
		arg.Summary,
		arg.Location,
		arg.Url,
		arg.StartDate,
		arg.StartPrecision,
		arg.EndDate,
		arg.EndPrecision,
		arg.IsCurrent,
		arg.Details,
		arg.AutoInclude,
		arg.ContentHash,
		arg.Position,
	)
	var version int32
	err := row.Scan(&version)
	return version, err
}

const upsertHighlight = `-- name: UpsertHighlight :execrows
INSERT INTO highlight (id, user_id, evidence_id, text, metric_value, metric_unit, auto_include, position, content_hash)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (id) DO UPDATE SET
    text = EXCLUDED.text, metric_value = EXCLUDED.metric_value, metric_unit = EXCLUDED.metric_unit,
    auto_include = EXCLUDED.auto_include, position = EXCLUDED.position, content_hash = EXCLUDED.content_hash
WHERE highlight.user_id = EXCLUDED.user_id AND highlight.evidence_id = EXCLUDED.evidence_id
`

type UpsertHighlightParams struct {
	ID          uuid.UUID
	UserID      uuid.UUID
	EvidenceID  uuid.UUID
	Text        string
	MetricValue *float64
	MetricUnit  string
	AutoInclude bool
	Position    string
	ContentHash []byte
}

func (q *Queries) UpsertHighlight(ctx context.Context, arg UpsertHighlightParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertHighlight,
		arg.ID,
		arg.UserID,
		arg.EvidenceID,
		arg.Text,
		arg.MetricValue,
		arg.MetricUnit,
		arg.AutoInclude,
		arg.Position,
		arg.ContentHash,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
